const exercises=[
{id:'bench',name:'Barbell bench press',group:'Upper body',equipment:'Barbell',base:80,reps:8,tips:['Lie on the bench with your feet planted and shoulder blades pulled back.','Grip slightly wider than shoulder width. Lower the bar under control to your mid-chest.','Press up while keeping your wrists stacked over your forearms. Use a spotter for heavy attempts.']},
{id:'squat',name:'Barbell back squat',group:'Lower body',equipment:'Barbell',base:110,reps:6,tips:['Set the bar across your upper back and stand with feet about shoulder width apart.','Brace your core, bend your hips and knees, and lower to a comfortable depth.','Drive through your whole foot to stand, keeping your knees in line with your toes.']},
{id:'deadlift',name:'Conventional deadlift',group:'Lower body',equipment:'Barbell',base:140,reps:5,tips:['Stand with the bar over mid-foot and grip just outside your legs.','Brace, hinge at the hips, and keep the bar close as you stand up.','Lower with control. Avoid rounding your lower back; start with a manageable load.']},
{id:'overhead',name:'Overhead press',group:'Upper body',equipment:'Barbell',base:50,reps:8,tips:['Hold the bar at your shoulders with your elbows slightly in front.','Brace your core and press overhead without leaning back.','Bring the bar down under control.']},
{id:'row',name:'Bent-over barbell row',group:'Upper body',equipment:'Barbell',base:70,reps:10,tips:['Hinge at your hips and keep your back neutral.','Pull the bar toward your lower ribs without swinging your torso.','Lower smoothly and keep your core braced.']},
{id:'pullup',name:'Weighted pull-up',group:'Upper body',equipment:'Pull-up bar',base:20,reps:6,tips:['Use a secure belt to add weight; logged weight is added load only.','Start in a controlled hang, then pull until your chin clears the bar.','Lower slowly through your comfortable range.']},
{id:'incline',name:'Incline dumbbell press',group:'Upper body',equipment:'Dumbbells',base:26,reps:10,tips:['Set the bench to a moderate incline and plant your feet.','Lower the dumbbells beside your chest with control.','Press up; log the weight of one dumbbell.']},
{id:'rdl',name:'Romanian deadlift',group:'Lower body',equipment:'Barbell',base:70,reps:10,tips:['Stand tall with the bar close to your thighs.','With a slight knee bend, push your hips back and lower until you feel a hamstring stretch.','Keep your back neutral and return to standing by driving your hips forward.']},
{id:'curl',name:'Dumbbell biceps curl',group:'Upper body',equipment:'Dumbbells',base:14,reps:12,tips:['Stand with elbows close to your sides.','Curl without swinging; squeeze at the top.','Lower slowly. Log the weight of one dumbbell.']}
];
// A bundled snapshot; loading the catalog never sends workout data to an API.
const snapshot=window.REPCLUB_CATALOG||{exercises:[],source:'wger',snapshotDate:''};
const coreSourceIds={bench:73,squat:1801,deadlift:184,overhead:687,row:83,pullup:475,incline:537,rdl:507,curl:92};
for(const e of exercises){const source=snapshot.exercises.find(x=>x.sourceId===coreSourceIds[e.id]);Object.assign(e,{mode:'weight',bodyPart:e.group==='Lower body'?'Legs':e.id==='bench'||e.id==='incline'?'Chest':e.id==='overhead'?'Shoulders':e.id==='curl'?'Arms':'Back',images:source?.images||[],muscles:source?.muscles||[],sourceId:source?.sourceId,sourceUrl:source?.sourceUrl,sourceAuthor:source?.sourceAuthor,license:source?.license,licenseUrl:source?.licenseUrl});}
for(const e of snapshot.exercises){if(!Object.entries(coreSourceIds).some(([id,n])=>id!=='pullup'&&n===e.sourceId))exercises.push(e);}
const modeFor=id=>exercises.find(e=>e.id===id)?.mode||'weight';
const isNewBest=(id,s,old)=>!old||(modeFor(id)==='weight'?s.weight>old.weight:s.reps>old.reps);
const validSet=(id,s)=>Number.isFinite(s.weight)&&s.weight>=0&&s.weight<=1000&&Number.isInteger(s.reps)&&s.reps>=1&&s.reps<=(modeFor(id)==='time'?86400:modeFor(id)==='reps'?1000:100);
const setLabel=(id,s)=>modeFor(id)==='time'?fmt(s.reps)+' sec':modeFor(id)==='reps'?fmt(s.reps)+' reps':fmt(s.weight)+' kg × '+s.reps;
const recordNumber=(id,r)=>r?fmt(modeFor(id)==='weight'?r.weight:r.reps):'—';
const recordUnit=id=>modeFor(id)==='time'?'sec':modeFor(id)==='reps'?'reps':'kg';
let bodyPartFilter='All',equipmentFilter='All',illustratedOnly=false,libraryLimit=24;
const routines=[{id:'upper',name:'Upper body club',tag:'PUSH + PULL',description:'A little push. A little pull. A whole lot of progress.',ids:['bench','row','overhead','incline','curl'],minutes:45},{id:'lower',name:'Leg day, good day',tag:'LOWER BODY',description:'Build your base. Your future self will thank you.',ids:['squat','rdl','deadlift'],minutes:50},{id:'full',name:'The full-body remix',tag:'FULL BODY',description:'All the big moves, in one feel-good session.',ids:['squat','bench','row','overhead'],minutes:55}];
if(exercises.some(e=>e.id==='wger_1551'))routines.push({id:'bodyweight',name:'Bodyweight, big energy',tag:'BODYWEIGHT',description:'Push-ups, pull-ups, squats, and a little core. No plates required.',ids:['wger_1551','wger_475','wger_1312','wger_458'].filter(id=>exercises.some(e=>e.id===id)),minutes:30});
function seed(){const workouts=[];for(let w=7;w>=0;w--){for(const day of [1,3,5]){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7)-w*7+day-1);if(d>new Date())continue;const r=day===3?routines[1]:routines[0];workouts.push({id:uid(),date:localDate(d),name:r.name,duration:r.minutes+(w%3)*3,exercises:r.ids.map(id=>{const e=exercises.find(x=>x.id===id);return{id,sets:[0,1,2].map(()=>({weight:Math.max(5,e.base-w*2.5),reps:e.reps,done:true}))}}),prs:w===0?[r.ids[0]]:[]})}}return{version:1,name:'Friend',goal:4,plan:['rest','upper','rest','lower','rest','upper','full'],workouts,manualRecords:[],body:[{date:offsetDate(-56),weight:74.8},{date:offsetDate(-42),weight:74.2},{date:offsetDate(-28),weight:73.9},{date:offsetDate(-14),weight:73.5},{date:offsetDate(-7),weight:73.3},{date:localDate(),weight:73.1}],session:null,demo:true}}
function offsetDate(n){const d=new Date();d.setDate(d.getDate()+n);return localDate(d)}
const STORAGE='repclub-v1';let storageAvailable=true;let state;try{state=JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{state=null}if(!state||!Array.isArray(state.workouts)||state.version!==1)state=seed();let currentPage='overview',recordFilter='All lifts',libraryFilter='All',chartRange='8W',search='',timerDeadline=0,timerPaused=90,timerInterval;let dirtySession=false;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false;toast('Device storage is unavailable. Export a backup before closing.')}const badge=$('.local-badge');if(badge)badge.innerHTML=`<i></i> ${storageAvailable?'Saved on this device':'Storage unavailable'}`}
save();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
function recordFor(id){const sets=[];for(const w of state.workouts)for(const e of w.exercises||[])if(e.id===id)for(const s of e.sets||[])if(s.done&&s.reps>0&&(modeFor(id)!=='weight'||s.weight>0))sets.push({...s,date:w.date});for(const r of state.manualRecords||[])if(r.id===id)sets.push({...r,done:true});sets.sort((a,b)=>(modeFor(id)==='weight'?b.weight-a.weight:0)||b.reps-a.reps||b.date.localeCompare(a.date));return sets[0]||null}
function volume(w){return(w.exercises||[]).reduce((a,e)=>a+(modeFor(e.id)==='weight'?(e.sets||[]).filter(s=>s.done).reduce((b,s)=>b+s.weight*s.reps,0):0),0)}
function sortedWorkouts(){return[...state.workouts].sort((a,b)=>b.date.localeCompare(a.date))}
function weekStart(){const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return localDate(d)}
function stats(){const month=localDate().slice(0,7),ws=weekStart(),weekly=state.workouts.filter(w=>w.date>=ws&&w.date<=localDate()),monthly=state.workouts.filter(w=>w.date.startsWith(month));return{weekly,monthly,volume:monthly.reduce((a,w)=>a+volume(w),0),prs:monthly.reduce((a,w)=>a+(w.prs||[]).length,0)+(state.manualRecords||[]).filter(r=>r.date.startsWith(month)&&r.newBest).length,minutes:monthly.reduce((a,w)=>a+w.duration,0)}}
function streakWeeks(){let count=0;const monday=new Date(weekStart()+'T12:00:00');for(let i=0;i<104;i++){const start=new Date(monday);start.setDate(start.getDate()-i*7);const end=new Date(start);end.setDate(end.getDate()+7);const has=state.workouts.some(w=>w.date>=localDate(start)&&w.date<localDate(end));if(!has&&i===0)continue;if(!has)break;count++}return count}
const navPages=[['overview','Overview'],['workout','Workout'],['plan','My plan'],['records','Personal records'],['progress','Progress'],['library','Exercise library']];
function renderNav(){const count=exercises.filter(e=>recordFor(e.id)).length;$('#navigation').innerHTML=navPages.map(([id,label])=>`<button class="nav-button ${currentPage===id?'active':''}" data-page="${id}" ${currentPage===id?'aria-current="page"':''}>${icon(id)}${label}${id==='records'?`<span class="nav-count">${count}</span>`:''}</button>`).join('');if($('#mobileNavigation'))$('#mobileNavigation').innerHTML=navPages.filter(([id])=>id!=='plan').map(([id,label])=>`<button class="mobile-nav-item ${currentPage===id?'active':''}" data-page="${id}" ${currentPage===id?'aria-current="page"':''}>${icon(id)}${id==='records'?'PRs':id==='library'?'Exercises':label}</button>`).join('');$('#profileName').textContent=state.name;$('.avatar').textContent=state.name.charAt(0).toUpperCase();$('.small-avatar').textContent=state.name.charAt(0).toUpperCase()}
function heading(title,subtitle='',action='',eyebrow='YOUR TRAINING, YOUR WAY'){return`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p class="subtext">${subtitle}</p>`:''}</div>${action}</div>`}
function navigate(page){if(!['overview','workout','plan','records','progress','library','settings','history'].includes(page))page='overview';currentPage=page;if(location.hash!==`#${page}`)history.replaceState(null,'',`#${page}`);renderNav();$('#breadcrumb').textContent=({settings:'Preferences',history:'Workout history',records:'Personal records',plan:'My plan',library:'Exercise library'}[page]||page.charAt(0).toUpperCase()+page.slice(1));$('#main').innerHTML=({overview:overview,workout:workoutPage,plan:planPage,records:recordsPage,progress:progressPage,library:libraryPage,settings:settingsPage,history:historyPage}[page])();$('.app').classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');if(page==='workout')updateSessionSummary();window.scrollTo({top:0,behavior:'instant'})}
function statsStrip(){const s=stats();return`<div class="stats-strip"><div class="stat"><div class="stat-label">${icon('workout')} Workouts this month</div><div class="stat-bottom"><span class="stat-number">${String(s.monthly.length).padStart(2,'0')}</span><span class="change">${s.weekly.length} this week</span></div></div><div class="stat"><div class="stat-label">${icon('workout')} Volume lifted</div><div class="stat-bottom"><span class="stat-number">${fmt(s.volume/1000)}<small>t</small></span><span class="change">This month</span></div></div><div class="stat"><div class="stat-label">${icon('records')} New personal records</div><div class="stat-bottom"><span class="stat-number">${String(s.prs).padStart(2,'0')}</span><span class="change">Keep them coming</span></div></div><div class="stat"><div class="stat-label">${icon('clock')} Time well spent</div><div class="stat-bottom"><span class="stat-number">${fmt(s.minutes/60)}<small>hrs</small></span><span class="change">This month</span></div></div></div>`}
function overview(){const today=new Date(),hour=today.getHours(),greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';const planned=routines.find(r=>r.id===state.plan[today.getDay()]),routine=planned||routines[0];const s=stats(),record=recordFor('deadlift');return`${heading(`${greeting}, ${esc(state.name)} <span class="asterisk">✳</span>`,'',`<button class="button" data-action="start-default">${icon('plus')} ${state.session?'Resume workout':'Log a workout'}</button>`,`${today.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}).toUpperCase()} <span class="sun">☀</span>`)}<div class="top-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow">${planned?"ON THE MENU TODAY":"YOUR NEXT GOOD SESSION"} <span>↗</span></div><h2 class="hero-title">${routine.id==='upper'?'A little push.<span>A little pull.</span>':routine.id==='lower'?'Leg day.<span>Good day.</span>':'Full body.<span>Full send.</span>'}</h2><div class="hero-info"><span>${routine.name}</span><span>•</span><span>${routine.ids.length} exercises</span><span>•</span><span>~${routine.minutes} min</span></div></div><div class="hero-art">${weightArt}</div><div class="hero-actions"><button class="button dark" data-action="start" data-routine="${routine.id}">${state.session?'Resume workout':'Let’s get to it'} ${icon('arrow')}</button><span class="tiny-pill">${planned?'YOU’VE GOT THIS':'REST DAY? YOUR CALL.'}</span></div><span class="hero-spark" aria-hidden="true">✳</span></section><section class="streak-card"><div class="eyebrow">CONSISTENCY LOOKS GOOD ON YOU</div><div class="streak-big">${String(streakWeeks()).padStart(2,'0')}<span>week streak</span></div><div class="flame">${flame}</div><p>You keep showing up.<br>That’s where the magic happens.</p><div class="week-days">${[1,2,3,4,5,6,0].map((day,i)=>{const d=new Date(weekStart()+'T12:00:00');d.setDate(d.getDate()+i);const logged=state.workouts.some(w=>w.date===localDate(d));return`<div class="week-day">${days[day].slice(0,1)}<div class="week-dot ${logged?'done':day===today.getDay()?'today':''}" title="${days[day]}: ${logged?'workout logged':'no workout'}">${logged?'✓':day===today.getDay()?'•':'–'}</div></div>`}).join('')}</div></section></div>${statsStrip()}<div class="middle-grid"><section class="panel"><div class="panel-top"><h2>Little by little, stronger.</h2><div class="segmented" aria-label="Chart time range">${['4W','8W'].map(r=>`<button data-action="range" data-range="${r}" class="${chartRange===r?'selected':''}">${r}</button>`).join('')}</div></div>${volumeChart()}<div class="chart-caption"><span><i></i>Weekly training volume</span><span>•</span><span>Every rep counts</span></div></section><section class="panel"><div class="panel-top"><h2>The trophy shelf</h2><button class="link-button" data-page="records">View all ↗</button></div><div class="pr-preview"><div class="eyebrow">YOUR HEAVIEST HITTER ✦</div><h3>Conventional deadlift</h3><div class="pr-weight">${record?fmt(record.weight):'—'} <small>kg${record?` × ${record.reps} reps`:''}</small></div><div class="pr-date">${record?shortDate(record.date)+' · Personal best':'Log a lift to start your collection'}</div><div class="trophy-illustration">${trophy}</div></div>${['bench','squat'].map(id=>{const e=exercises.find(e=>e.id===id),r=recordFor(id);return`<button class="pr-mini text-button wide-button" data-action="record-detail" data-id="${id}"><strong>${e.name.replace('Barbell ','')}</strong><span>${r?fmt(r.weight)+' kg':'No record yet'} ↗</span></button>`}).join('')}</section></div><section class="bottom-section"><div class="section-heading"><h2>Recently, you showed up.</h2><button class="link-button" data-page="history">All workouts ↗</button></div>${historyRows(sortedWorkouts().slice(0,3))}</section><p class="sample-note">${state.demo?'Sample history is included so you can explore. Start fresh in Preferences whenever you’re ready.':`${s.weekly.length} of ${state.goal} weekly workouts complete. Keep showing up.`}</p>`}
function weeklyVolumes(count){const start=new Date(weekStart()+'T12:00:00');const result=[];for(let i=count-1;i>=0;i--){const d=new Date(start);d.setDate(d.getDate()-i*7);const end=new Date(d);end.setDate(end.getDate()+7);result.push({label:shortDate(localDate(d)),value:state.workouts.filter(w=>w.date>=localDate(d)&&w.date<localDate(end)).reduce((n,w)=>n+volume(w),0)})}return result}
function lineChart(data,suffix='t',scale=1000){const max=Math.max(...data.map(x=>x.value),1)*1.2;const coordinates=data.map((d,i)=>[40+i*(440/Math.max(data.length-1,1)),135-d.value/max*116]);const points=coordinates.map(p=>p.join(',')).join(' ');return`<svg class="chart" viewBox="0 0 510 170" role="img" aria-label="${esc(data.map(d=>d.label+': '+fmt(d.value/scale)+' '+suffix).join('; '))}"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#25c6e4" stop-opacity=".22"/><stop offset="1" stop-color="#25c6e4" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="40" y1="${19+i*38.6}" x2="490" y2="${19+i*38.6}" stroke="#3b3b37" stroke-dasharray="3 5"/><text x="0" y="${22+i*38.6}">${fmt(max*(1-i/3)/scale)}${suffix}</text>`).join('')}<polygon points="40,135 ${points} 480,135" fill="url(#chartFill)"/><polyline points="${points}" fill="none" stroke="#25c6e4" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${coordinates.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${i===data.length-1?4:2.5}" fill="#25c6e4"><title>${esc(data[i].label)}: ${fmt(data[i].value/scale)} ${suffix}</title></circle>`).join('')}${data.map((d,i)=>`<text x="${coordinates[i][0]}" y="159" text-anchor="middle">${esc(d.label)}</text>`).join('')}</svg>`}
function volumeChart(){const data=weeklyVolumes(chartRange==='4W'?4:8),last=data.at(-1)?.value||0,prev=data.at(-2)?.value||0,change=prev?Math.round((last-prev)/prev*100):0;return`<div class="chart-summary"><strong>${fmt(last/1000)}<small> t</small></strong><small>this week</small><span class="growth">${change>=0?'↗':'↘'} ${Math.abs(change)}% vs last week</span></div>${lineChart(data)}`}
function historyRows(workouts){if(!workouts.length)return'<div class="empty-state">Your first workout is the start of something good.</div>';return workouts.map(w=>`<div class="history-row"><div class="history-name"><div class="workout-icon">${icon('workout')}</div><div><strong>${esc(w.name)}</strong><small>${shortDate(w.date)} · ${w.exercises.length} exercises${w.prs?.length?` · <span class="pr-badge">${w.prs.length} PR${w.prs.length>1?'s':''} ✦</span>`:''}</small></div></div><div class="history-col">${w.duration} min<small>Duration</small></div><div class="history-col">${fmt(volume(w)/1000)} t<small>Total volume</small></div><button data-action="history-detail" data-id="${esc(w.id)}" aria-label="View ${esc(w.name)} on ${shortDate(w.date)}">↗</button></div>`).join('')}
function planPage(){return`${heading('A week with a little rhythm.','Make room for the things that make you stronger.',`<button class="button outline" data-action="weekly-goal">Weekly goal: ${state.goal} sessions</button>`,'YOUR PLAN')}<div class="week-grid">${[1,2,3,4,5,6,0].map(day=>{const r=routines.find(r=>r.id===state.plan[day]);return`<section class="plan-day ${day===new Date().getDay()?'today':''}"><div class="day-label">${days[day].slice(0,3).toUpperCase()} ${day===new Date().getDay()?'<span class="cyan">TODAY</span>':''}</div><h3>${r?r.name:'Rest & recharge'}</h3><p>${r?`${r.ids.length} exercises<br>~${r.minutes} minutes`:'A little recovery.<br>A little fresh air.'}</p><button data-action="edit-day" data-day="${day}">Change ↗</button></section>`}).join('')}</div><div class="section-heading mt"><h2>Your go-to routines</h2><span class="date-label">Good plans, better reps.</span></div><div class="routine-grid">${routines.map(r=>`<section class="panel routine-card"><span class="routine-tag">${r.tag}</span><h3>${r.name}</h3><p>${r.ids.map(id=>exercises.find(e=>e.id===id).name).join('<br>')}</p><button class="button" data-action="start" data-routine="${r.id}">${state.session?'Resume workout':'Start this routine'} ${icon('arrow')}</button></section>`).join('')}</div>`}
function progressPage(){const s=stats(),latest=[...state.body].sort((a,b)=>b.date.localeCompare(a.date))[0];return`${heading('Look how far you’ve come.','Progress isn’t always loud. Sometimes it’s just one more rep.',`<button class="button" data-action="weigh-in">${icon('plus')} Log body weight</button>`,'THE BIGGER PICTURE')}${statsStrip()}<div class="progress-grid"><section class="panel"><div class="panel-top"><h2>Volume, on the up.</h2><div class="segmented">${['4W','8W'].map(r=>`<button data-action="range" data-range="${r}" class="${chartRange===r?'selected':''}">${r}</button>`).join('')}</div></div>${volumeChart()}<p class="chart-note">Total load × reps across completed sets. This week is still in progress.</p></section><section class="panel"><div class="panel-top"><h2>Body weight</h2><span class="date-label">kg</span></div><div class="chart-summary"><strong>${latest?fmt(latest.weight):'—'}<small> kg</small></strong><small>${latest?shortDate(latest.date):'No entries yet'}</small></div>${state.body.length?lineChart([...state.body].sort((a,b)=>a.date.localeCompare(b.date)).slice(-8).map(b=>({label:shortDate(b.date),value:b.weight})),'',1):'<div class="empty-state">Add your first weigh-in to see your chart.</div>'}<p class="chart-note">Your body is more than a number. Look at the trend, not one day.</p></section></div><section class="panel mt"><div class="panel-top"><h2>The showing-up calendar</h2><span class="date-label">Last 16 weeks</span></div><div class="heatmap">${Array.from({length:112},(_,i)=>{const d=offsetDate(i-111),minutes=state.workouts.filter(w=>w.date===d).reduce((a,w)=>a+w.duration,0);return`<span class="${minutes?minutes<30?'level1':minutes<50?'level2':'level3':''}" title="${shortDate(d)}: ${minutes} minutes"></span>`}).join('')}</div><div class="heatmap-key"><span>Every colored square is a day you showed up.</span><span>Less ▪ ▪ <span class="cyan">▪</span> More</span></div></section>`}
function lastSetFor(id){for(const w of sortedWorkouts()){const e=w.exercises.find(x=>x.id===id);const sets=e?.sets.filter(s=>s.done);if(sets?.length)return sets[sets.length-1]}return null}
function makeExercise(id){const e=exercises.find(e=>e.id===id),r=lastSetFor(id);return{instance:uid(),id,sets:[0,1,2].map(()=>({weight:modeFor(id)==='weight'?(r?r.weight:e.id.startsWith('wger_')?0:e.base):0,reps:r?r.reps:e.reps,done:false}))}}
function startRoutine(id){if(state.session){navigate('workout');toast('Your current session is ready to resume.');return}const r=routines.find(r=>r.id===id)||routines[0];state.session={id:uid(),name:r.name,startedAt:Date.now(),exercises:r.ids.map(makeExercise)};save();navigate('workout')}
function timerSeconds(){return timerDeadline?Math.max(0,Math.ceil((timerDeadline-Date.now())/1000)):timerPaused}
function timerText(){const n=timerSeconds();return`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function updateSessionSummary(){if(!state.session||!$('#completedSets'))return;const done=state.session.exercises.flatMap(e=>e.sets).filter(s=>s.done);const elapsed=Math.floor((Date.now()-state.session.startedAt)/1000);$('#completedSets').textContent=`${done.length} / ${state.session.exercises.reduce((a,e)=>a+e.sets.length,0)}`;$('#sessionVolume').textContent=fmt(state.session.exercises.reduce((a,e)=>a+(modeFor(e.id)==='weight'?e.sets.filter(s=>s.done).reduce((n,s)=>n+s.weight*s.reps,0):0),0))+' kg';$('#sessionElapsed').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`}
function finishWorkout(){const session=state.session,completed=session.exercises.filter(e=>e.sets.some(s=>s.done)).map(e=>({...e,sets:e.sets.filter(s=>s.done)}));if(!completed.length){toast('Complete at least one set to save your workout.');return}const prs=completed.filter(e=>{const old=recordFor(e.id);return e.sets.some(s=>(modeFor(e.id)!=='weight'||s.weight>0)&&isNewBest(e.id,s,old))}).map(e=>e.id);const w={id:uid(),date:localDate(),name:session.name,duration:Math.max(1,Math.round((Date.now()-session.startedAt)/60000)),exercises:completed,prs};state.workouts.push(w);state.session=null;timerDeadline=0;timerPaused=90;save();navigate('overview');modal(`<div class="modal-star">✳</div><div class="eyebrow">ANOTHER ONE IN THE BOOKS</div><h2 class="modal-title">Look at you, showing up.</h2><p class="subtext">${completed.reduce((a,e)=>a+e.sets.length,0)} sets · ${completionSummary(w)} · ${w.duration} minutes well spent.</p>${prs.length?`<div class="achievement-bar"><div><h3>${prs.length} new personal record${prs.length>1?'s':''}! ✦</h3><p>${prs.map(id=>esc(exercises.find(e=>e.id===id).name)).join(', ')}</p></div></div>`:''}<button class="button yellow mt" data-action="close-modal">Feeling a little stronger ${icon('check')}</button>`)}
function historyPage(){return`${heading('Your very own highlight reel.','Every session has a place here.',`<button class="button" data-action="start-default">${icon('plus')} Log a workout</button>`,'WORKOUT HISTORY')}<section class="panel history-page">${historyRows(sortedWorkouts())}</section>`}
function baseSettingsPage(){return`${heading('Make yourself at home.','Your little corner of the club, just how you like it.','','PREFERENCES')}<section class="panel settings-panel"><form id="preferencesForm"><div class="field"><label for="name">What should we call you?</label><input id="name" name="name" required maxlength="30" value="${esc(state.name)}"></div><div class="field"><label for="goal">Weekly workout goal</label><select id="goal" name="goal">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===state.goal?'selected':''}>${n} sessions per week</option>`).join('')}</select></div><button class="button yellow" type="submit">Save preferences ${icon('check')}</button></form><div class="settings-section"><h3>Your data goes where you go.</h3><p>Workouts, personal records, weigh-ins, and your plan are saved in this browser on this device. Export a backup to keep them safe or move to another device.</p><div class="settings-actions"><button class="button outline" data-action="export">Export backup ↗</button><button class="button outline" data-action="import">Import backup ↙</button><input type="file" id="importFile" accept="application/json,.json" hidden></div></div><div class="settings-section"><h3>${state.demo?'Ready to make it yours?':'A fresh page, whenever you need it.'}</h3><p>${state.demo?'You’re currently exploring sample workouts, PRs, and weight entries. Start fresh to build your own history. Your name and weekly plan will stay.':'Clear your training history and records, keeping your name and plan.'}</p><div class="settings-actions"><button class="button outline danger" data-action="clear-history">Start fresh</button><button class="button outline" data-action="restore-demo">Restore sample data</button></div></div><div class="settings-section"><h3>A little inspiration. An original club.</h3><p>Inspired by openGym’s focus on simple workout tracking and your visual references. Repclub is an original browser-based experience. Loads are logged in kilograms. There is no cross-device sync in this version.</p><a class="link-button" href="https://opengym.ch/" target="_blank" rel="noopener">Visit openGym ↗</a></div></section>`}
function confirmation(title,detail,action,id=''){modal(`<h2 class="modal-title">${title}</h2><p class="subtext">${detail}</p><button class="button yellow" data-action="${action}" data-id="${esc(id)}">Yes, go ahead</button><button class="button outline mt" data-action="close-modal">Keep things as they are</button>`)}
function validBackup(data){const num=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00'))&&localDate(new Date(v+'T12:00:00'))===v&&v<=localDate();const set=s=>s&&num(s.weight,0,1000)&&num(s.reps,1,86400)&&Number.isInteger(s.reps)&&typeof s.done==='boolean';return data&&data.version===1&&typeof data.name==='string'&&data.name.length>0&&data.name.length<=30&&num(data.goal,1,7)&&Number.isInteger(data.goal)&&Array.isArray(data.plan)&&data.plan.length===7&&data.plan.every(x=>['rest',...routines.map(r=>r.id)].includes(x))&&Array.isArray(data.workouts)&&data.workouts.length<=10000&&data.workouts.every(w=>w&&typeof w.id==='string'&&typeof w.name==='string'&&w.name.length<=100&&date(w.date)&&num(w.duration,0,1440)&&Array.isArray(w.exercises)&&w.exercises.every(e=>exercises.some(x=>x.id===e.id)&&Array.isArray(e.sets)&&e.sets.length<=100&&e.sets.every(s=>validSet(e.id,s)&&typeof s.done==='boolean'))&&Array.isArray(w.prs)&&w.prs.every(id=>exercises.some(x=>x.id===id)))&&Array.isArray(data.manualRecords)&&data.manualRecords.length<=10000&&data.manualRecords.every(r=>exercises.some(e=>e.id===r.id)&&num(r.weight,modeFor(r.id)==='weight'?.5:0,1000)&&num(r.reps,1,modeFor(r.id)==='time'?86400:modeFor(r.id)==='reps'?1000:100)&&Number.isInteger(r.reps)&&date(r.date))&&Array.isArray(data.body)&&data.body.length<=10000&&data.body.every(b=>date(b.date)&&num(b.weight,20,500))&&typeof data.demo==='boolean'}
document.addEventListener('click',event=>{const button=event.target.closest('button, [data-page]');if(!button)return;if(button.dataset.page){navigate(button.dataset.page);return}const a=button.dataset.action,id=button.dataset.id,instance=button.dataset.instance,e=state.session?.exercises.find(e=>e.instance===instance);switch(a){case'start-default':startRoutine(state.plan[new Date().getDay()]);break;case'start':startRoutine(button.dataset.routine);break;case'empty-workout':if(state.session){navigate('workout');break}state.session={id:uid(),name:'My little stronger session',startedAt:Date.now(),exercises:[]};save();navigate('workout');break;case'range':chartRange=button.dataset.range;navigate(currentPage);break;case'record-filter':recordFilter=button.dataset.filter;navigate('records');break;case'library-filter':libraryFilter=button.dataset.filter;libraryLimit=24;navigate('library');break;case'record-detail':recordDetail(id);break;case'add-pr':openPR(id);break;case'exercise-detail':exerciseDetail(id);break;case'add-exercise':if(!state.session)state.session={id:uid(),name:'My little stronger session',startedAt:Date.now(),exercises:[]};if(state.session.exercises.some(e=>e.id===id)){toast('That lift is already in your session.');break}state.session.exercises.push(makeExercise(id));save();$('#modal').close();navigate('workout');toast('Exercise added. Let’s make it count.');break;case'session-add':exercisePicker();break;case'session-add-confirm':{const chosen=$('#sessionExercise').value;if(!chosen){toast('All library exercises are already in this session.');break}state.session.exercises.push(makeExercise(chosen));save();$('#modal').close();navigate('workout');break}case'add-set':if(!e)break;const last=e.sets.at(-1)||{weight:20,reps:8};e.sets.push({weight:last.weight,reps:last.reps,done:false});save();navigate('workout');break;case'remove-exercise':confirmation('Remove this exercise?','Its sets will be removed from your current session.','confirm-remove-exercise',instance);break;case'confirm-remove-exercise':state.session.exercises=state.session.exercises.filter(e=>e.instance!==id);save();$('#modal').close();navigate('workout');break;case'complete-set':{if(!e)break;const s=e.sets[Number(button.dataset.set)];if(!validSet(e.id,s)){toast(modeFor(e.id)==='time'?'Enter a duration from 1–86,400 whole seconds.':modeFor(e.id)==='reps'?'Enter 1–1,000 whole reps.':'Enter a weight from 0–1,000 kg and 1–100 whole reps.');break}s.done=!s.done;if(s.done){timerPaused=90;timerDeadline=Date.now()+90000;const old=recordFor(e.id);if((modeFor(e.id)!=='weight'||s.weight>0)&&isNewBest(e.id,s,old))toast('Strong moment! Finish your workout to save this new PR.')}save();button.classList.toggle('checked',s.done);button.setAttribute('aria-pressed',String(s.done));button.closest('tr').classList.toggle('completed',s.done);button.setAttribute('aria-label',`${s.done?'Unmark':'Complete'} set ${Number(button.dataset.set)+1}`);if($('#timerToggle'))$('#timerToggle').textContent=timerDeadline?'Pause':'Start';updateSessionSummary();break}case'rest-toggle':if(timerDeadline){timerPaused=timerSeconds();timerDeadline=0}else{if(timerPaused<=0)timerPaused=90;timerDeadline=Date.now()+timerPaused*1000}$('#timerToggle').textContent=timerDeadline?'Pause':'Start';$('#restDisplay').textContent=timerText();break;case'rest-add':case'rest-sub':{const sec=Math.max(0,Math.min(600,timerSeconds()+(a==='rest-add'?30:-30)));if(timerDeadline)timerDeadline=Date.now()+sec*1000;else timerPaused=sec;$('#restDisplay').textContent=timerText();break}case'finish-workout':finishWorkout();break;case'discard-workout':confirmation('Call this one off?','This will discard the current session and all its unsaved sets.','confirm-discard');break;case'confirm-discard':state.session=null;timerDeadline=0;timerPaused=90;save();$('#modal').close();navigate('workout');toast('Session discarded. A fresh start awaits.');break;case'close-modal':$('#modal').close();break;case'edit-day':{const day=Number(button.dataset.day);modal(`<div class="eyebrow">YOUR WEEK, YOUR RHYTHM</div><h2 class="modal-title">What’s on for ${days[day]}?</h2><form id="dayForm" data-day="${day}"><div class="field mt"><label for="dayRoutine">Routine</label><select id="dayRoutine" name="routine"><option value="rest">Rest & recharge</option>${routines.map(r=>`<option value="${r.id}" ${state.plan[day]===r.id?'selected':''}>${r.name}</option>`).join('')}</select></div><button class="button yellow">Save day ${icon('check')}</button></form>`);break}case'weekly-goal':modal(`<h2 class="modal-title">Set your weekly rhythm.</h2><p class="subtext">Pick a goal that feels good and fits your life.</p><form id="goalForm"><div class="field"><label for="goalCount">Sessions per week</label><select id="goalCount" name="goal">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===state.goal?'selected':''}>${n}</option>`).join('')}</select></div><button class="button yellow">Save weekly goal</button></form>`);break;case'weigh-in':modal(`<div class="eyebrow">A SMALL CHECK-IN</div><h2 class="modal-title">How’s your body doing?</h2><p class="subtext">One data point, not the whole story.</p><form id="weighForm"><div class="field"><label for="bodyWeight">Body weight (kg)</label><input id="bodyWeight" name="weight" type="number" required min="20" max="500" step="0.1" placeholder="73.1"></div><div class="field"><label for="bodyDate">Date</label><input id="bodyDate" name="date" type="date" required value="${localDate()}" max="${localDate()}"></div><button class="button yellow">Save check-in ${icon('check')}</button></form>`);break;case'history-detail':historyDetail(id);break;case'delete-workout':confirmation('Remove this workout?','This session will leave your history. Your personal records and progress will be recalculated.','confirm-delete-workout',id);break;case'confirm-delete-workout':state.workouts=state.workouts.filter(w=>w.id!==id);save();$('#modal').close();navigate('history');toast('Workout removed. Progress recalculated.');break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`repclub-backup-${localDate()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your backup is on its way.');break}case'import':$('#importFile').click();break;case'clear-history':confirmation('A clean slate?','This clears workouts, records, weigh-ins, and your active session. Export a backup first if you want to keep them. Your name and plan stay.','confirm-clear');break;case'confirm-clear':state.workouts=[];state.manualRecords=[];state.body=[];state.session=null;state.demo=false;timerDeadline=0;timerPaused=90;save();$('#modal').close();navigate('overview');toast('Fresh page. Your first rep starts here.');break;case'restore-demo':confirmation('Bring back the sample club?','This replaces your current training history and plan with sample data. Export a backup first to keep your entries.','confirm-restore');break;case'confirm-restore':{const name=state.name;state=seed();state.name=name;timerDeadline=0;timerPaused=90;save();$('#modal').close();navigate('overview');toast('The sample club is back.');break}case'confirm-import':{const imported=window.pendingImport;if(!imported)break;state=imported;state.session=null;window.pendingImport=null;timerDeadline=0;timerPaused=90;save();$('#modal').close();navigate('overview');toast('Welcome back. Your backup is restored.');break}}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='exerciseSearch'){search=el.value;libraryLimit=24;updateLibraryResults()}if(el.dataset.field&&state.session){const e=state.session.exercises.find(e=>e.instance===el.dataset.instance);if(!e)return;const s=e.sets[Number(el.dataset.set)];const n=el.value===''?NaN:Number(el.value);s[el.dataset.field]=n;if(s.done){s.done=false;const tr=el.closest('tr');tr.classList.remove('completed');const button=tr.querySelector('.set-check');button.classList.remove('checked');button.setAttribute('aria-pressed','false');button.setAttribute('aria-label',`Complete set ${Number(el.dataset.set)+1}`)}save();updateSessionSummary()}});
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();const f=new FormData(form);switch(form.id){case'preferencesForm':state.name=String(f.get('name')).trim()||'Friend';state.goal=Number(f.get('goal'));save();navigate('settings');toast('Your space, updated.');break;case'prForm':{const id=String(f.get('exercise')),weight=Number(f.get('weight')),reps=Number(f.get('reps')),date=String(f.get('date'));if(!exercises.some(e=>e.id===id)||!validSet(id,{weight,reps})||(modeFor(id)==='weight'&&weight<=0)||!date||date>localDate())return;const old=recordFor(id),newBest=isNewBest(id,{weight,reps},old);state.manualRecords.push({id,weight,reps,date,newBest});save();$('#modal').close();navigate('records');toast(newBest?'New personal best! Make room on the shelf.':'Set saved. Your trophy shelf keeps your best.');break}case'dayForm':state.plan[Number(form.dataset.day)]=String(f.get('routine'));save();$('#modal').close();navigate('plan');toast('Your week has a new rhythm.');break;case'goalForm':state.goal=Number(f.get('goal'));save();$('#modal').close();navigate('plan');toast('Your weekly goal is set.');break;case'weighForm':{const weight=Number(f.get('weight')),date=String(f.get('date'));if(weight<20||weight>500||!Number.isFinite(weight)||date>localDate())return;const existing=state.body.find(b=>b.date===date);if(existing)existing.weight=weight;else state.body.push({weight,date});save();$('#modal').close();navigate('progress');toast('Check-in saved. Keep looking at the big picture.');break}}});
document.addEventListener('change',async event=>{if(event.target.id!=='importFile')return;const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('That backup is too large. Choose a file smaller than 5 MB.');event.target.value='';return}try{const data=JSON.parse(await file.text());if(!validBackup(data))throw new Error('Invalid backup');window.pendingImport=data;confirmation('Bring your club back?','Importing replaces your current history and plan with this backup. Your active session will be cleared.','confirm-import')}catch{toast('That file isn’t a valid Repclub backup. Please try another.')}event.target.value=''});
$('#menuToggle').addEventListener('click',()=>{const open=$('.app').classList.toggle('menu-open');$('#menuToggle').setAttribute('aria-expanded',String(open))});
$('#closeModal').addEventListener('click',()=>$('#modal').close());
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#modal').close()}});
$('#helpButton').addEventListener('click',()=>modal(`<div class="modal-star">✳</div><div class="eyebrow">WELCOME TO YOUR LITTLE STRONGER CLUB</div><h2 class="modal-title">One rep at a time.</h2><p class="subtext">Log a workout, build a weekly rhythm, and watch your personal records grow. Sample history is included to help you explore.</p><ul class="detail-list"><li><span>01</span>Start a routine and check off your completed sets.</li><li><span>02</span>Finish the workout to save your history and new PRs.</li><li><span>03</span>Your data stays in this browser. Export a backup in Preferences.</li></ul><button class="button yellow" data-action="close-modal">I’m in ${icon('arrow')}</button>`));
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
timerInterval=setInterval(()=>{if(timerDeadline&&Date.now()>=timerDeadline){timerDeadline=0;timerPaused=0;toast('Breather’s over. Ready for the next set?');if($('#timerToggle'))$('#timerToggle').textContent='Start'}if($('#restDisplay'))$('#restDisplay').textContent=timerText();updateSessionSummary()},1000);
navigate(location.hash.slice(1)||'overview');
// Extended local exercise catalog and measurement-aware workout screens.
function normalized(value){return String(value).toLowerCase().replace(/[^a-z0-9]/g,'')}
function catalogFiltered(){const needle=normalized(search);return exercises.filter(e=>(libraryFilter==='All'||e.group===libraryFilter)&&(bodyPartFilter==='All'||e.bodyPart===bodyPartFilter)&&(equipmentFilter==='All'||e.equipment.toLowerCase().includes(equipmentFilter.toLowerCase()))&&(!illustratedOnly||e.images?.length)&&(!needle||normalized([e.name,e.equipment,e.bodyPart,...(e.muscles||[]),e.sourceId===1551?'pushups push ups push up':'',e.sourceId===475?'pullups pull ups pull up':''].join(' ')).includes(needle))).sort((a,b)=>{const featured=['wger_1551','wger_475','bench','squat','deadlift','wger_458','wger_1312','wger_984','overhead','row'];const x=featured.indexOf(a.id),y=featured.indexOf(b.id);return(x<0?100:x)-(y<0?100:y)||a.name.localeCompare(b.name)})}
function measureTag(e){return`<span class="mode-tag ${e.mode==='reps'?'bodyweight':e.mode==='time'?'timed':''}">${e.mode==='time'?'TIMED HOLD / CARDIO':e.mode==='reps'?'BODYWEIGHT · REPS':'LOAD + REPS'}</span>`}
function exerciseVisual(e){return e.images?.length?`<img src="${esc(e.images[0].src)}" alt="${esc(e.name)} demonstration" loading="lazy" decoding="async" width="600" height="600">`:`<span class="bodypart-mark" aria-hidden="true">${e.bodyPart==='Cardio'?'↗':e.bodyPart==='Abs'?'◎':'✳'}</span><span class="no-reference">${esc(e.bodyPart||e.group)} · source has no image</span>`}
function exerciseCards(list){return list.length?list.map(e=>`<section class="panel exercise-card"><div class="exercise-visual">${exerciseVisual(e)}</div><div class="exercise-info"><h3>${esc(e.name)}</h3><p>${esc(e.bodyPart||e.group)} · ${esc(e.equipment)}</p>${measureTag(e)}<br><button data-action="exercise-detail" data-id="${e.id}">View ${e.images?.length?'images & ':''}instructions ↗</button></div></section>`).join(''):'<div class="empty-state">No exercises match these filters. Try fewer filters or a different name.</div>'}
function libraryPage(){const groups=['All','Upper body','Lower body','Core','Cardio'];const parts=[...new Set(exercises.map(e=>e.bodyPart).filter(Boolean))].sort();const list=catalogFiltered();return`${heading('More moves. More possibilities.','Pull-ups, push-ups, big lifts, and all the little things in between.','','THE OFFLINE EXERCISE LIBRARY')}<div class="library-controls"><input id="exerciseSearch" class="search-field exercise-search-field" placeholder="Search exercise, muscle, or equipment…" aria-label="Search exercises" value="${esc(search)}"><div class="records-toolbar">${groups.map(f=>`<button class="filter-chip ${libraryFilter===f?'active':''}" data-action="library-filter" data-filter="${f}">${f}</button>`).join('')}</div></div><div class="catalog-controls"><select id="bodyPartFilter" aria-label="Filter by body part"><option value="All">All muscle groups</option>${parts.map(p=>`<option value="${esc(p)}" ${p===bodyPartFilter?'selected':''}>${esc(p)}</option>`).join('')}</select><select id="equipmentFilter" aria-label="Filter by equipment"><option value="All">All equipment</option>${['Bodyweight','Barbell','Dumbbell','Kettlebell','Cable','Machine','Resistance band','Pull-up bar','Bench'].map(p=>`<option value="${p}" ${p===equipmentFilter?'selected':''}>${p}</option>`).join('')}</select><label class="catalog-toggle"><input id="illustratedFilter" type="checkbox" ${illustratedOnly?'checked':''}> With reference images</label></div><div class="library-summary"><span id="libraryCount">${list.length} exercises · showing ${Math.min(libraryLimit,list.length)}</span><span>Stored with the app · no live API</span></div><div id="exerciseResults" class="exercise-grid">${exerciseCards(list.slice(0,libraryLimit))}</div><div id="libraryMore">${list.length>libraryLimit?'<button class="button outline library-load-more" data-action="library-more">Show 24 more exercises +</button>':''}</div><p class="dataset-footnote">${exercises.length} exercises · wger community dataset snapshot ${esc(snapshot.snapshotDate)}. Images are shown where supplied by the source; missing images are clearly marked. Instructions and image credits are included in each exercise.</p>`}
function updateLibraryResults(){if(!$('#exerciseResults'))return;const list=catalogFiltered();$('#exerciseResults').innerHTML=exerciseCards(list.slice(0,libraryLimit));$('#libraryCount').textContent=`${list.length} exercises · showing ${Math.min(libraryLimit,list.length)}`;$('#libraryMore').innerHTML=list.length>libraryLimit?'<button class="button outline library-load-more" data-action="library-more">Show 24 more exercises +</button>':''}
function exerciseDetail(id){const e=exercises.find(e=>e.id===id);if(!e)return;const images=e.images||[];const credits=images.map((i,j)=>`<div>Image ${j+1}: ${esc(i.author)} · <a href="${esc(i.licenseUrl)}" target="_blank" rel="noopener">${esc(i.license)}</a> · <a href="${esc(i.sourceUrl)}" target="_blank" rel="noopener">Source</a>. ${esc(i.changes)}</div>`).join('');modal(`<div class="eyebrow">${esc(e.bodyPart||e.group).toUpperCase()} · ${esc(e.equipment).toUpperCase()}</div><h2 class="modal-title">${esc(e.name)}</h2>${measureTag(e)}${images.length?`<div class="demo-strip ${images.length===1?'single':''}">${images.map((i,j)=>`<figure><img src="${esc(i.src)}" alt="${esc(e.name)}, reference image ${j+1}" decoding="async"><figcaption>REFERENCE ${j+1}</figcaption></figure>`).join('')}</div>`:'<div class="image-placeholder">This source entry has no reference image. Its written instructions are included below.</div>'}<div class="exercise-metadata">${e.muscles?.length?`Primary muscles: ${esc(e.muscles.join(', '))}<br>`:''}Logging: ${e.mode==='reps'?'bodyweight repetitions':e.mode==='time'?'duration in seconds':e.id==='pullup'?'added load in kilograms + repetitions':'load in kilograms + repetitions'}${e.id==='pullup'?'<br>The source demonstration is unweighted. Log only the extra load for this weighted variation.':''}</div><ul class="detail-list">${e.tips.map((tip,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span>${esc(tip)}</li>`).join('')}</ul><button class="button yellow" data-action="add-exercise" data-id="${id}">${state.session?'Add to current workout':'Start a workout with this exercise'} ${icon('plus')}</button><div class="source-credit">${e.sourceUrl?`Exercise source: <a href="${esc(e.sourceUrl)}" target="_blank" rel="noopener">wger</a> · ${esc(e.sourceAuthor||'wger contributors')} · <a href="${esc(e.licenseUrl)}" target="_blank" rel="noopener">${esc(e.license)}</a>. Text extracted from the source for offline display.<br>`:'Repclub exercise notes.<br>'}${credits}</div>`)}
function pickerRows(term=''){return exercises.filter(e=>!state.session?.exercises.some(x=>x.id===e.id)&&(!term||normalized([e.name,e.equipment,...(e.muscles||[])].join(' ')).includes(normalized(term)))).slice(0,30).map(e=>`<button class="picker-row" data-action="add-exercise" data-id="${e.id}">${e.images?.length?`<img src="${esc(e.images[0].src)}" alt="" loading="lazy">`:''}<div><strong>${esc(e.name)}</strong><small>${esc(e.bodyPart||e.group)} · ${e.mode==='reps'?'Reps':e.mode==='time'?'Seconds':'Load + reps'}</small></div><span>+</span></button>`).join('')||'<p class="subtext">No matching exercises. Try another name.</p>'}
function exercisePicker(){modal(`<div class="eyebrow">ONE MORE GOOD MOVE</div><h2 class="modal-title">Build your session.</h2><input id="exercisePickerSearch" class="search-field library-search-modal" placeholder="Search ${exercises.length} exercises…" aria-label="Find an exercise to add"><div id="exercisePickerResults" class="exercise-picker">${pickerRows()}</div>`)}
function workoutPage(){if(!state.session)return`${heading('Ready when you are.','Pick a routine or build your own from the exercise library.','','LET’S MOVE')}<div class="routine-grid">${routines.map(r=>`<section class="panel routine-card"><span class="routine-tag">${r.tag}</span><h3>${r.name}</h3><p>${r.description}</p><p>${r.ids.length} exercises · ~${r.minutes} min</p><button class="button yellow" data-action="start" data-routine="${r.id}">Let’s do this ${icon('arrow')}</button></section>`).join('')}</div><button class="button outline mt" data-action="empty-workout">${icon('plus')} Build my own workout</button>`;const session=state.session;return`${heading(esc(session.name),'Saved loads are filled in. Adjust every set for today.',`<button class="button outline" data-action="session-add">${icon('plus')} Add exercise</button>`,'WORKOUT IN PROGRESS · SAVED ON THIS DEVICE')}<div class="session-layout"><div>${session.exercises.map((entry,i)=>{const e=exercises.find(x=>x.id===entry.id),mode=modeFor(e.id),last=lastSetFor(e.id);return`<section class="panel session-exercise"><div class="panel-top"><div class="session-exercise-head">${e.images?.length?`<img class="session-thumb" src="${esc(e.images[0].src)}" alt="${esc(e.name)} reference" loading="lazy">`:''}<div><span class="eyebrow">EXERCISE ${String(i+1).padStart(2,'0')} · ${mode==='reps'?'BODYWEIGHT':mode==='time'?'TIMED':'LOAD + REPS'}</span><h3 style="margin-top:8px">${esc(e.name)}</h3><button class="form-link" data-action="exercise-detail" data-id="${e.id}">View form & instructions ↗</button></div></div><button class="icon-button" data-action="remove-exercise" data-instance="${entry.instance}" aria-label="Remove ${esc(e.name)}">×</button></div><table class="set-table"><thead><tr><th>SET</th><th>LAST TIME</th>${mode==='weight'?'<th>KG</th>':''}<th>${mode==='time'?'SECONDS':'REPS'}</th><th>DONE</th></tr></thead><tbody>${entry.sets.map((set,j)=>`<tr class="${set.done?'completed':''}"><td>${j+1}</td><td class="muted">${last?setLabel(e.id,last):'—'}</td>${mode==='weight'?`<td><input type="number" inputmode="decimal" min="0" max="1000" step="0.5" value="${set.weight??''}" data-instance="${entry.instance}" data-set="${j}" data-field="weight" aria-label="${esc(e.name)} set ${j+1} weight in kilograms"></td>`:''}<td><input type="number" inputmode="numeric" min="1" max="${mode==='time'?86400:mode==='reps'?1000:100}" step="1" value="${set.reps??''}" data-instance="${entry.instance}" data-set="${j}" data-field="reps" aria-label="${esc(e.name)} set ${j+1} ${mode==='time'?'seconds':'reps'}"></td><td><button class="set-check ${set.done?'checked':''}" data-action="complete-set" data-instance="${entry.instance}" data-set="${j}" aria-label="${set.done?'Unmark':'Complete'} set ${j+1}" aria-pressed="${set.done}">✓</button></td></tr>`).join('')}</tbody></table><button class="add-set" data-action="add-set" data-instance="${entry.instance}">+ Add a set</button></section>`}).join('')||'<section class="panel empty-state">Add an exercise to build your session.</section>'}</div><aside class="panel session-sidebar"><div class="panel-top"><h2>A little breather.</h2><span class="date-label">REST TIMER</span></div><div class="timer-display" id="restDisplay">${timerText()}</div><div class="rest-controls"><button class="button outline" data-action="rest-sub">−30s</button><button class="button cyan" id="timerToggle" data-action="rest-toggle">${timerDeadline?'Pause':'Start'}</button><button class="button outline" data-action="rest-add">+30s</button></div><div class="session-summary"><div class="summary-row"><span>Time in the club</span><strong id="sessionElapsed">00:00</strong></div><div class="summary-row"><span>Sets complete</span><strong id="completedSets">0</strong></div><div class="summary-row"><span>Weighted volume lifted</span><strong id="sessionVolume">0 kg</strong></div></div><button class="button yellow" data-action="finish-workout">That’s a wrap ${icon('check')}</button><button class="text-button danger wide-button" style="font-size:10px;padding-top:20px" data-action="discard-workout">Discard session</button></aside></div>`}
function recordsPage(){const list=exercises.filter(e=>recordFor(e.id)).filter(e=>recordFilter==='All lifts'||e.group===recordFilter);return`${heading('Your strong moments. <span class="asterisk">✦</span>','Heaviest loads. Most reps. Longest holds. All your own.',`<button class="button yellow" data-action="add-pr">${icon('plus')} Log a PR</button>`,'THE PERSONAL RECORDS CLUB')}<div class="records-toolbar">${['All lifts','Upper body','Lower body','Core','Cardio'].map(f=>`<button class="filter-chip ${recordFilter===f?'active':''}" data-action="record-filter" data-filter="${f}">${f}</button>`).join('')}</div><div class="record-grid">${list.length?list.map((e,i)=>{const r=recordFor(e.id);return`<button class="panel record-card ${i===0?'featured':''}" style="text-align:left" data-action="record-detail" data-id="${e.id}"><div class="eyebrow">${e.group.toUpperCase()} · ${e.mode==='reps'?'MOST REPS':e.mode==='time'?'LONGEST DURATION':'HEAVIEST SET'}</div><h3>${esc(e.name)}</h3><div class="pr-weight">${recordNumber(e.id,r)} <small>${recordUnit(e.id)}</small></div><div class="trophy-illustration">${trophy}</div><div class="record-bottom"><span>${e.mode==='weight'?r.reps+' reps · ':''}${shortDate(r.date)}</span><span>View record ↗</span></div></button>`}).join(''):'<div class="panel empty-state">Your trophy shelf is waiting. Finish your first workout or log a personal best.</div>'}</div><div class="achievement-bar"><span class="star">✳</span><div><h3>Your only competition is yesterday’s you.</h3><p>Load, bodyweight reps, and timed holds each have their own record. All saved on this device.</p></div></div>`}
function recordDetail(id){const e=exercises.find(e=>e.id===id),r=recordFor(id);if(!e)return;modal(`<div class="eyebrow">PERSONAL RECORD · ${e.group.toUpperCase()}</div><h2 class="modal-title">${esc(e.name)}</h2>${r?`<div class="record-detail-value">${recordNumber(id,r)} <small style="font-size:22px">${recordUnit(id)}${e.mode==='weight'?' × '+r.reps:''}</small></div><p class="subtext">${e.mode==='weight'?'Heaviest logged set':e.mode==='time'?'Longest logged duration':'Most reps in one set'} · ${shortDate(r.date)}</p>${e.mode==='weight'&&r.reps<=12&&id!=='pullup'?`<div class="achievement-bar"><div><h3>~${fmt(r.weight*(1+r.reps/30))} kg estimated 1RM</h3><p>Epley estimate, not a tested max.</p></div></div>`:''}<ul class="detail-list">${sortedWorkouts().filter(w=>w.exercises.some(x=>x.id===id)).slice(0,4).map(w=>`<li><span>${shortDate(w.date)}</span>${w.exercises.find(x=>x.id===id).sets.filter(s=>s.done).map(s=>setLabel(id,s)).join(' / ')}</li>`).join('')}</ul>`:'<p class="subtext">No record yet. Your first one starts here.</p>'}<button class="button yellow" data-action="add-pr" data-id="${id}">Log a new best ${icon('plus')}</button>`)}
function prFields(id){const mode=modeFor(id);return`${mode==='weight'?'<div class="field"><label for="prWeight">Weight (kg)</label><input id="prWeight" name="weight" type="number" inputmode="decimal" min="0.5" max="1000" step="0.5" required placeholder="80"></div>':'<input type="hidden" name="weight" value="0">'}<div class="field"><label for="prReps">${mode==='time'?'Best duration (seconds)':mode==='reps'?'Best reps in one set':'Reps'}</label><input id="prReps" name="reps" type="number" inputmode="numeric" min="1" max="${mode==='time'?86400:mode==='reps'?1000:100}" step="1" required value="${mode==='weight'?1:mode==='time'?30:10}"></div>`}
function openPR(id='bench'){if($('#modal').open)$('#modal').close();modal(`<div class="eyebrow">MAKE ROOM ON THE TROPHY SHELF</div><h2 class="modal-title">A new strong moment.</h2><p class="subtext">Your heaviest load, most bodyweight reps, or longest hold.</p><form id="prForm"><div class="field"><label for="prExercise">Exercise</label><select id="prExercise" name="exercise">${exercises.map(e=>`<option value="${e.id}" ${e.id===id?'selected':''}>${esc(e.name)} · ${recordUnit(e.id)}</option>`).join('')}</select></div><div id="prFields" class="modal-row">${prFields(id)}</div><div class="field"><label for="prDate">Date</label><input id="prDate" name="date" type="date" required value="${localDate()}" max="${localDate()}"></div><button class="button yellow">Add to the trophy shelf ✦</button></form>`)}
function historyDetail(id){const w=state.workouts.find(w=>w.id===id);if(!w)return;modal(`<div class="eyebrow">${shortDate(w.date).toUpperCase()} · ${w.duration} MINUTES</div><h2 class="modal-title">${esc(w.name)}</h2><p class="subtext">${fmt(volume(w))} kg weighted volume${w.prs?.length?` · ${w.prs.length} new PRs`:''}</p><ul class="detail-list">${w.exercises.map(e=>`<li><strong>${esc(exercises.find(x=>x.id===e.id)?.name||e.id)}</strong><br>${e.sets.filter(s=>s.done).map(s=>setLabel(e.id,s)).join(' · ')}</li>`).join('')}</ul><button class="button outline danger" data-action="delete-workout" data-id="${id}">Delete this workout</button>`)}
function settingsPage(){const installSection=`<div class="offline-card"><img src="icon-192.png" alt="Repclub app icon"><div><h3>Your gym buddy. In your pocket.</h3><p>Install Repclub on your Android home screen and train offline.</p></div></div><div class="settings-actions"><button class="button yellow" data-install-app>Install app ↗</button><button class="button outline" data-retry-offline>Download for offline</button><button class="button outline" data-update-app>Check ready update</button></div><p class="device-status" id="offlineDetail">Keep this page open online until the top status says “Ready offline”.</p><p class="privacy-line">Your workout data lives on this device. No cloud sync, uploads, tracking, or remote AI.</p><div class="settings-section"></div>`;return baseSettingsPage().replace('<section class="panel settings-panel">','<section class="panel settings-panel">'+installSection).replace('Repclub is an original browser-based experience. Loads are logged in kilograms. There is no cross-device sync in this version.','Repclub is an installable offline web app. The first app download and future updates use the internet; your training data stays on your device. Load is logged in kg, bodyweight exercises in reps, and timed activities in seconds.').replace('</section>',`<div class="settings-section"><h3>A sourced exercise library.</h3><p>${exercises.length} exercises from a bundled wger community database snapshot (${esc(snapshot.snapshotDate)}), with equipment, muscles, written instructions, and available reference images. Individual source and Creative Commons credits appear in each exercise. The app makes no live dataset requests while you train.</p><a class="link-button" href="exercise-sources.json" download="Repclub-Exercise-Sources.json">Download source snapshot & credits ↙</a></div></section>`)}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action="library-more"]');if(b){libraryLimit+=24;updateLibraryResults()}});
document.addEventListener('input',event=>{if(event.target.id==='exercisePickerSearch')$('#exercisePickerResults').innerHTML=pickerRows(event.target.value)});
document.addEventListener('change',event=>{const id=event.target.id;if(id==='prExercise')$('#prFields').innerHTML=prFields(event.target.value);if(['bodyPartFilter','equipmentFilter','illustratedFilter'].includes(id)){if(id==='bodyPartFilter')bodyPartFilter=event.target.value;if(id==='equipmentFilter')equipmentFilter=event.target.value;if(id==='illustratedFilter')illustratedOnly=event.target.checked;libraryLimit=24;updateLibraryResults()}});
document.addEventListener('error',event=>{if(event.target.tagName==='IMG'){event.target.alt='Reference image unavailable';event.target.classList.add('missing-image')}},true);

function completionSummary(w){const parts=[],v=volume(w),reps=w.exercises.filter(e=>modeFor(e.id)==='reps').reduce((n,e)=>n+e.sets.reduce((a,s)=>a+s.reps,0),0),seconds=w.exercises.filter(e=>modeFor(e.id)==='time').reduce((n,e)=>n+e.sets.reduce((a,s)=>a+s.reps,0),0);if(v>0)parts.push(fmt(v)+' kg moved');if(reps)parts.push(fmt(reps)+' bodyweight reps');if(seconds)parts.push(fmt(seconds)+' seconds of timed work');return parts.join(' · ')||'no added load'}
